const since = Date.now() - 7 * 24 * 60 * 60 * 1000;
const rows = $input.all().map(i => i.json);
const recent = rows.filter(r => new Date(r.submitted_at || r.sent_at || r.delivered_at || r.failed_at || r.last_reply_at || 0).getTime() >= since);
const leads = recent.filter(r => r.email && (r.submitted_at || r.delivery_status));
const sends = recent.filter(r => r.sequence_step || r.status === 'failed');
const count = (xs, test) => xs.filter(test).length;
const magnets = {}; leads.forEach(r => { if (r.magnet_name) magnets[r.magnet_name] = (magnets[r.magnet_name] || 0) + 1; });
const replies = {}; leads.forEach(r => { if (r.reply_category) replies[r.reply_category] = (replies[r.reply_category] || 0) + 1; });
return [{json:{period_start:new Date(since).toISOString(),leads_last_7_days:leads.length,consent_rate:leads.length ? Math.round(100*count(leads,r=>String(r.nurture_opt_in)==='true')/leads.length) : 0,delivery_failures:count(sends,r=>r.status==='failed' && r.sequence_step==='delivery'),sequence_completion:leads.length ? Math.round(100*count(sends,r=>r.sequence_step==='nurture_2' && r.status==='sent')/leads.length) : 0,reply_categories:replies,top_magnets:Object.entries(magnets).sort((a,b)=>b[1]-a[1]).slice(0,3)}}];
